function invertTree(root) {
  if (!root || root.length === 0) return [];
  class Node {
    constructor(val) {
      this.val = val;
      this.left = null;
      this.right = null;
    }
  }
  const rootNode = new Node(root[0]);
  const q = [rootNode];
  let i = 1;
  while (q.length && i < root.length) {
    const curr = q.shift();
    if (i < root.length && root[i] !== null) {
      curr.left = new Node(root[i]);
      q.push(curr.left);
    }
    i++;
    if (i < root.length && root[i] !== null) {
      curr.right = new Node(root[i]);
      q.push(curr.right);
    }
    i++;
  }
  function invert(node) {
    if (!node) return null;
    const temp = node.left;
    node.left = invert(node.right);
    node.right = invert(temp);
    return node;
  }
  invert(rootNode);
  const res = [];
  const outQ = [rootNode];
  while (outQ.length) {
    const curr = outQ.shift();
    if (curr) {
      res.push(curr.val);
      outQ.push(curr.left);
      outQ.push(curr.right);
    }
  }
  return res;
}

